ALTER TABLE public.appointment_slots
  ADD COLUMN IF NOT EXISTS data_source text NOT NULL DEFAULT 'manual',
  ADD COLUMN IF NOT EXISTS is_demo_record boolean NOT NULL DEFAULT false;

ALTER TABLE public.appointment_types
  ADD COLUMN IF NOT EXISTS data_source text NOT NULL DEFAULT 'manual',
  ADD COLUMN IF NOT EXISTS is_demo_record boolean NOT NULL DEFAULT false;

-- Every appointment type and slot currently in the database was generated by the
-- demo seed scripts: the imported staff sheet contains no availability data.
UPDATE public.appointment_types SET data_source = 'seed', is_demo_record = true;
UPDATE public.appointment_slots SET data_source = 'seed', is_demo_record = true;

CREATE OR REPLACE FUNCTION public.list_appointment_availability(
  _unit_code text DEFAULT NULL::text,
  _type_query text DEFAULT NULL::text,
  _from timestamp with time zone DEFAULT now(),
  _to timestamp with time zone DEFAULT (now() + '30 days'::interval),
  _limit integer DEFAULT 60)
 RETURNS TABLE(slot_id uuid, start_time timestamp with time zone, end_time timestamp with time zone, seats_left integer, type_id uuid, type_name_en text, type_name_ar text, duration_minutes integer, location_type text, requires_approval boolean, unit_id uuid, unit_code text, unit_name_en text, unit_name_ar text, unit_email text, staff_id uuid, staff_name text, staff_email text, location text, meeting_link text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT s.id, s.start_time, s.end_time, (s.capacity - s.booked_count)::int,
         t.id, t.name_en, t.name_ar, t.duration_minutes, t.location_type, t.requires_approval,
         u.id, u.code, u.name_en, u.name_ar, COALESCE(u.contact_email, u.email),
         sp.user_id, p.full_name, p.email,
         s.location, s.meeting_link
    FROM public.appointment_slots s
    JOIN public.appointment_types t ON t.id = s.appointment_type_id
    LEFT JOIN public.service_units u ON u.id = t.service_unit_id
    LEFT JOIN public.staff_profiles sp ON sp.user_id = s.staff_profile_id
    LEFT JOIN public.profiles p ON p.id = s.staff_profile_id
   WHERE auth.uid() IS NOT NULL
     AND s.status = 'open'
     AND s.is_demo_record = false
     AND t.is_demo_record = false
     AND s.booked_count < s.capacity
     AND t.is_active
     AND s.start_time >= GREATEST(_from, now())
     AND s.start_time <= _to
     AND (_unit_code IS NULL OR u.code = _unit_code)
     AND (_type_query IS NULL OR (t.name_en || ' ' || t.name_ar) ILIKE '%' || _type_query || '%')
   ORDER BY s.start_time
   LIMIT GREATEST(1, LEAST(_limit, 200));
$function$;